 code=[("password_check.py", 'def check_password(password):\n    return {\n        "length >= 12": len(password) >= 12,\n        "has uppercase": any(c.isupper() for c in password),\n        "has lowercase": any(c.islower() for c in password),\n        "has digit": any(c.isdigit() for c in password),\n        "has symbol": any(not c.isalnum() for c in password),\n    }\n\nfor rule, ok in check_password("Str0ng!Passw0rd").items():\n    print(f"[{\'PASS\' if ok else \'FAIL\'}] {rule}")')],
