 code=[("organizer.py", 'from pathlib import Path\n\nCATEGORIES = {".jpg": "images", ".png": "images", ".pdf": "documents", ".txt": "documents", ".mp3": "audio"}\n\ndef classify(path):\n    return CATEGORIES.get(path.suffix.lower(), "other")\n\ndef plan_moves(folder):\n    return [(p, Path(folder) / classify(p) / p.name) for p in Path(folder).iterdir() if p.is_file()]\n\ndef apply_moves(moves, dry_run=True):\n    for src, dst in moves:\n        if dry_run:\n            print(f"Would move: {src.name} -> {dst}")\n        else:\n            dst.parent.mkdir(parents=True, exist_ok=True)\n            src.rename(dst)\n\napply_moves(plan_moves("downloads"), dry_run=True)')],
