CAPSTONE = [
dict(id="capstone-arch", idx="CAP.1", title="معماری و درخت فایل", ctx="ساختار کامل PulseOps",
 what="**مسئله:** ابزار محلی واحدی می‌خواهی که وظایف شخصی را ردیابی کند، گاهی یک داده‌ی خارجی را از یک API عمومی بگیرد، همه را در یک دیتابیس نگه دارد و گزارش روزانه‌ی خوانا بسازد. **هدف:** یک CLI نصب‌شدنی به‌نام `pulseops` با فرمان‌های مدیریت وظیفه، دریافت داده و گزارش؛ کاملاً تست‌شده و مستند.",
 steps=["افزودن/تکمیل/فهرست وظیفه با اولویت و تاریخ سررسید در SQLite", "دریافت یک مقدار از API عمومی و ذخیره‌ی snapshot زمان‌دار", "ساخت گزارش روزانه از وظایف باز و آخرین snapshot", "تنظیمات (مسیر دیتابیس، URL) از متغیر محیطی با پیش‌فرض‌های معقول", "لاگ کامل رویدادها بدون ثبت هیچ رازی", "مجموعه‌تست pytest روی خدمات با دیتابیس درون‌حافظه"],
 code=[("ساختار پروژه", "pulseops/\n├── pyproject.toml\n├── requirements.txt\n├── README.md\n├── .env.example\n├── pulseops/\n│   ├── __init__.py\n│   ├── config.py          # تنظیمات از env\n│   ├── database.py        # طرح SQLite و کوئری‌های پارامتری\n│   ├── models.py          # dataclassها: Task، Snapshot\n│   ├── services.py        # add_task، save_snapshot، build_report\n│   ├── external_api.py    # بسته‌ی requests: timeout و خطا\n│   ├── cli.py             # نقطه‌ی ورود argparse\n│   └── logging_setup.py\n└── tests/\n    ├── test_services.py\n    └── test_external_api.py")],
 extra=[("اجزا", "`config.py` همه‌ی مقادیر وابسته به محیط را یک‌جا می‌خواند. `database.py` همه‌ی SQL (پارامتری) را دارد. `models.py` رکوردهای تایپ‌شده می‌سازد. `services.py` منطق خالص است و اتصال را به‌عنوان آرگومان می‌گیرد تا مستقل تست شود. `external_api.py` تنها ماژولی است که `requests` را import می‌کند؛ پس mock کردن همین یک ماژول کل مرز شبکه را می‌پوشاند. `cli.py` همه‌چیز را پشت زیرفرمان‌های `argparse` به هم وصل می‌کند.")]),
dict(id="capstone-code", idx="CAP.2", title="برنامه‌ی پیاده‌سازی و کد کلیدی", ctx="ماژول‌های اصلی PulseOps",
 steps=["**گام ۱:** `config.py` و `database.py`؛ ساخت طرح با دیتابیس فایلی و درون‌حافظه.", "**گام ۲:** `models.py` و توابع وظیفه در `services.py` (افزودن/فهرست/تکمیل) با تست، پیش از هر چیز شبکه‌ای.", "**گام ۳:** `external_api.py` با mock از ابتدا؛ هرگز تست را به شبکه‌ی زنده وابسته نکن.", "**گام ۴:** `build_report()` که وظایف و آخرین snapshot را ترکیب می‌کند.", "**گام ۵:** اتصال `cli.py` و در آخر README و `pyproject.toml` وقتی رفتار پایدار شد."],
 code=[("pulseops/models.py", "from dataclasses import dataclass\nfrom typing import Optional\n\n@dataclass\nclass Task:\n    id: Optional[int]\n    title: str\n    priority: str\n    due_date: str\n    done: bool = False\n\n@dataclass\nclass Snapshot:\n    id: Optional[int]\n    fetched_at: str\n    value: float"),
  ("pulseops/database.py", 'import sqlite3\n\ndef get_connection(path):\n    conn = sqlite3.connect(path)\n    with conn:\n        conn.execute("""CREATE TABLE IF NOT EXISTS tasks (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            title TEXT NOT NULL, priority TEXT NOT NULL,\n            due_date TEXT NOT NULL, done INTEGER NOT NULL DEFAULT 0)""")\n        conn.execute("""CREATE TABLE IF NOT EXISTS snapshots (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            fetched_at TEXT NOT NULL, value REAL NOT NULL)""")\n    return conn'),
  ("pulseops/services.py", 'from datetime import datetime\n\ndef add_task(conn, title, priority, due_date):\n    with conn:\n        conn.execute("INSERT INTO tasks (title, priority, due_date) VALUES (?, ?, ?)", (title, priority, due_date))\n\ndef complete_task(conn, task_id):\n    with conn:\n        conn.execute("UPDATE tasks SET done = 1 WHERE id = ?", (task_id,))\n\ndef list_open_tasks(conn):\n    return conn.execute("SELECT id, title, priority, due_date FROM tasks WHERE done = 0 ORDER BY due_date").fetchall()\n\ndef save_snapshot(conn, value):\n    with conn:\n        conn.execute("INSERT INTO snapshots (fetched_at, value) VALUES (?, ?)", (datetime.now().isoformat(timespec="minutes"), value))\n\ndef build_report(conn):\n    tasks = list_open_tasks(conn)\n    latest = conn.execute("SELECT fetched_at, value FROM snapshots ORDER BY id DESC LIMIT 1").fetchone()\n    lines = [f"PulseOps report — {datetime.now():%Y-%m-%d}", "", f"Open tasks: {len(tasks)}"]\n    for _, title, priority, due in tasks:\n        lines.append(f"  [{priority}] {title} (due {due})")\n    lines.append(f"\\nLatest snapshot: {latest[1]} (fetched {latest[0]})" if latest else "\\nNo snapshots fetched yet.")\n    return "\\n".join(lines)'),
  ("pulseops/external_api.py", 'import requests\n\ndef fetch_value(api_url, timeout=5):\n    try:\n        r = requests.get(api_url, timeout=timeout)\n        r.raise_for_status()\n        return r.json().get("value")\n    except requests.exceptions.RequestException as e:\n        print(f"Fetch failed: {e}")\n        return None')]),
dict(id="capstone-quality", idx="CAP.3", title="برنامه‌ی تست، بازبینی امنیتی و کارایی", ctx="تضمین کیفیت PulseOps",
 code=[("tests/test_services.py", 'import pytest\nfrom pulseops.database import get_connection\nfrom pulseops.services import add_task, complete_task, list_open_tasks, build_report\n\n@pytest.fixture\ndef conn():\n    c = get_connection(":memory:")\n    yield c\n    c.close()\n\ndef test_add_and_list_task(conn):\n    add_task(conn, "Write report", "high", "2026-10-01")\n    tasks = list_open_tasks(conn)\n    assert len(tasks) == 1 and tasks[0][1] == "Write report"\n\ndef test_completed_task_excluded(conn):\n    add_task(conn, "Old task", "low", "2026-09-01")\n    complete_task(conn, list_open_tasks(conn)[0][0])\n    assert list_open_tasks(conn) == []\n\ndef test_report_with_no_snapshot(conn):\n    add_task(conn, "Task A", "medium", "2026-11-01")\n    report = build_report(conn)\n    assert "No snapshots fetched yet" in report and "Task A" in report'),
  ("tests/test_external_api.py", 'from unittest.mock import patch, MagicMock\nimport requests\nfrom pulseops.external_api import fetch_value\n\n@patch("pulseops.external_api.requests.get")\ndef test_fetch_value_success(mock_get):\n    resp = MagicMock()\n    resp.raise_for_status.return_value = None\n    resp.json.return_value = {"value": 42.0}\n    mock_get.return_value = resp\n    assert fetch_value("https://example.com") == 42.0\n\n@patch("pulseops.external_api.requests.get")\ndef test_fetch_value_network_error_returns_none(mock_get):\n    mock_get.side_effect = requests.exceptions.Timeout()\n    assert fetch_value("https://example.com") is None')],
 extra=[("بازبینی امنیتی", "همه‌ی SQL با `?` پارامتری است. URL و کلید API از متغیر محیطی خوانده می‌شود، نه هاردکد و نه لاگ. هر درخواست خارجی `timeout` صریح دارد. هیچ `subprocess` یا `shell=True` در پروژه نیست؛ پس سطح حمله‌ی command injection صفر است. مسیر فایل دیتابیس از تنظیمات می‌آید نه از ورودی کنترل‌نشده؛ پس نگرانی path traversal نیست."),
  ("ملاحظات کارایی", "SQLite برای مقیاس یک ابزار شخصی (هزاران وظیفه و snapshot) بدون هیچ تنظیم ویژه‌ای کافی است. اگر `list_open_tasks` روی داده‌ی خیلی بزرگ‌تر بسیار زیاد صدا زده شد، اولین بهینه‌سازی ایندکس روی `(done, due_date)` است؛ فقط وقتی profile نشان داد لازم است، نه از قبل."),
  ("چک‌لیست مستندات", "README (کار ابزار، نصب، یک مثال از هر فرمان)؛ `.env.example` با تمام متغیرهای محیطی و مقادیر نمونه‌ی امن؛ docstring روی هر تابع عمومی؛ بخش «معماری» در README مطابق CAP.1."),
  ("گسترش", "اجرای زمان‌بندی‌شده (cron یا Task Scheduler) فرمان `pulseops fetch` برای ساخت تاریخچه‌ی واقعی، و گزینه‌ی `--format json` برای گزارش.")]),
]

